import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Spell Memory and Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/magic/memory-and-familiarity.md","filePath":"en/guide/magic/memory-and-familiarity.md"}'),n={name:"en/guide/magic/memory-and-familiarity.md"};function l(d,e,o,s,m,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="spell-memory-and-familiarity" tabindex="-1">Spell Memory and Familiarity <a class="header-anchor" href="#spell-memory-and-familiarity" aria-label="Permalink to &quot;Spell Memory and Familiarity&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Knowing a spell permanently differs from preparing it in Active Memory.</li><li>Familiarity improves fluency with each Core Pattern without consuming extra skillcap.</li><li>Unprepared spells may require reference time; capacity and delays remain unresolved.</li></ul><p>Knowing a spell and having it ready are different things. Familiarity belongs to each Core Pattern and consumes no extra skillcap.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td>Known</td><td>Learned permanently</td></tr><tr><td>Prepared in Active Memory</td><td>No extra lookup before normal casting</td></tr><tr><td>Known but unprepared</td><td>Extra reference/recall before normal casting</td></tr><tr><td>Learned / Practiced / Mastered</td><td>Shared fluency vocabulary, not three extra skills</td></tr></tbody></table><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Factor</th><th>Proposed direction</th></tr></thead><tbody><tr><td>Familiarity</td><td>Can shorten reference delay; knowledge does not decay away</td></tr><tr><td>INT</td><td>May support capacity and complex patterns</td></tr><tr><td>Meditation</td><td>May support rearrangement and preparation</td></tr><tr><td>Variants</td><td>Preparing a base spell may not prepare every variant</td></tr><tr><td>Books / grimoires</td><td>Useful references, not unlimited immediate readiness</td></tr></tbody></table><ul><li>Calendar absence should not punish fluency.</li><li>Facilities may maintain practice efficiently.</li><li>Capacity, delays, preparation costs and interruption rules remain open.</li><li>The combat test&#39;s 5 SA slots and martial modifiers do not assign magic numbers.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Finding Remove Curse while being chased could require visible reading and divided attention before normal casting. That is a proposed experience, not an implemented interface.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/familiarity.html">Shared Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Scrolls and grimoires</a> · <a href="/Syrolands-Public/en/game-design/magic/memory-and-familiarity.html">Full design</a></p><p><span id="shared-practice-states"></span></p>',15)])])}const y=a(n,[["render",l]]);export{h as __pageData,y as default};
